const [product, setProduct] = useState(null);
const [loading, setLoading] = useState(true);

const {
    cart,
    addToCart
} = useCart();

useEffect(() =>
{
    async function loadProduct()
    {
        setLoading(true);

        // دریافت محصول بر اساس شناسه موجود در URL
        const data = await getProductById(id);

        setProduct(data);
        setLoading(false);
    }

    loadProduct();
}, [id]);

// نمایش وضعیت بارگذاری
if (loading)
{
    return (
        <Loading />
    );
}

// اگر محصول پیدا نشد
if (!product)
{
    return (
        <EmptyState
            title="جزوه پیدا نشد"
            message="جزوه مورد نظر وجود ندارد یا از فروشگاه حذف شده است."
            action={
                <Link to="/shop">
                    بازگشت به فروشگاه
                </Link>
            }
        />
    );
}

// بررسی وجود محصول در سبد خرید
const cartItem = cart.find(
    (item) =>
        String(item.id) === String(product.id)
);

const isInCart = Boolean(cartItem);

const cartQuantity = cartItem
    ? Number(cartItem.quantity) || 1
    : 0;

return (
    <div className="product-details-page">
        {/* مسیر دسترسی */}
        <div className="product-details-breadcrumb">
            <Link to="/shop">
                فروشگاه
            </Link>

            <span>
                /
            </span>

            <span>
                {product.title}
            </span>
        </div>

        <section className="product-details">
            {/* تصویر محصول */}
            <div className="product-details-image">
                <img
                    src={
                        import.meta.env.BASE_URL +
                        product.image
                    }
                    alt={product.title}
                />
            </div>

            {/* اطلاعات محصول */}
            <div className="product-details-content">
                <h1>
                    {product.title}
                </h1>

                {product.teacher && (
                    <p className="product-details-teacher">
                        مدرس:
                        {" "}
                        {product.teacher}
                    </p>
                )}

                {product.category && (
                    <p className="product-details-category">
                        دسته‌بندی:
                        {" "}
                        {product.category}
                    </p>
                )}

                {/* مشخصات محصول */}
                <div className="product-details-info">
                    {product.pages && (
                        <div>
                            <span>
                                تعداد صفحات:
                            </span>

                            <strong>
                                {Number(product.pages).toLocaleString("fa-IR")}
                            </strong>
                        </div>
                    )}

                    {product.file && (
                        <div>
                            <span>
                                نوع فایل:
                            </span>

                            <strong>
                                {product.file}
                            </strong>
                        </div>
                    )}

                    {product.size && (
                        <div>
                            <span>
                                حجم:
                            </span>

                            <strong>
                                {product.size}
                            </strong>
                        </div>
                    )}
                </div>

                {/* توضیحات محصول */}
                {product.description && (
                    <div className="product-details-description">
                        <h2>
                            توضیحات
                        </h2>

                        <p>
                            {product.description}
                        </p>
                    </div>
                )}

                {/* قیمت و وضعیت سبد */}
                <div className="product-details-purchase">
                    <div>
                        <div className="product-details-price">
                            {Number(product.price).toLocaleString("fa-IR")}
                            {" "}
                            تومان
                        </div>

                        {isInCart && (
                            <div className="product-details-cart-status">
                                این محصول در سبد خرید شماست
                                {" "}
                                ({cartQuantity.toLocaleString("fa-IR")} عدد)
                            </div>
                        )}
                    </div>

                    {isInCart ? (
                        <Link to="/cart">
                            <Button>
                                مشاهده سبد خرید
                            </Button>
                        </Link>
                    ) : (
                        <Button
                            onClick={() =>
                            {
                                addToCart(product);
                            }}
                        >
                            افزودن به سبد خرید
                        </Button>
                    )}
                </div>
            </div>
        </section>
    </div>
);
